/// The index of VARIANT's combination of AXES (each axis's DEFAULTS where VARIANT names none of its values),
/// the last axis varying fastest, and the density's index.
fn index(axes: &[&[&str]], defaults: &[usize], variant: &[&str]) -> (usize, usize) {
    let mut i = 0;
    for (axis, default) in axes.iter().zip(defaults) {
        let k = axis.iter().position(|v| variant.contains(v)).unwrap_or(*default);
        i = i * axis.len() + k;
    }
    let d = DENSITIES.iter().position(|d| variant.contains(d)).unwrap_or(1);
    (i, d)
}

