/// Component ID's geometry for VARIANT.
pub fn geom(id: CompId, variant: &[&str]) -> Geom {
    match id {
        CompId::Row => {
            let (i, d) = index(ROW_AXES, ROW_DEFAULTS, variant);
            ROW_GEOM[i][d]
        }
        CompId::Button => {
            let (i, d) = index(BUTTON_AXES, BUTTON_DEFAULTS, variant);
            BUTTON_GEOM[i][d]
        }
        CompId::KeyHint => {
            let (i, d) = index(KEY_HINT_AXES, KEY_HINT_DEFAULTS, variant);
            KEY_HINT_GEOM[i][d]
        }
        CompId::AgentMark => {
            let (i, d) = index(AGENT_MARK_AXES, AGENT_MARK_DEFAULTS, variant);
            AGENT_MARK_GEOM[i][d]
        }
        CompId::Progress => {
            let (i, d) = index(PROGRESS_AXES, PROGRESS_DEFAULTS, variant);
            PROGRESS_GEOM[i][d]
        }
        CompId::SectionHeader => {
            let (i, d) = index(SECTION_HEADER_AXES, SECTION_HEADER_DEFAULTS, variant);
            SECTION_HEADER_GEOM[i][d]
        }
        CompId::Card => {
            let (i, d) = index(CARD_AXES, CARD_DEFAULTS, variant);
            CARD_GEOM[i][d]
        }
        CompId::Chip => {
            let (i, d) = index(CHIP_AXES, CHIP_DEFAULTS, variant);
            CHIP_GEOM[i][d]
        }
        CompId::StatusDot => {
            let (i, d) = index(STATUS_DOT_AXES, STATUS_DOT_DEFAULTS, variant);
            STATUS_DOT_GEOM[i][d]
        }
        CompId::RangeBar => {
            let (i, d) = index(RANGE_BAR_AXES, RANGE_BAR_DEFAULTS, variant);
            RANGE_BAR_GEOM[i][d]
        }
        CompId::TimeAxis => {
            let (i, d) = index(TIME_AXIS_AXES, TIME_AXIS_DEFAULTS, variant);
            TIME_AXIS_GEOM[i][d]
        }
        CompId::Tab => {
            let (i, d) = index(TAB_AXES, TAB_DEFAULTS, variant);
            TAB_GEOM[i][d]
        }
        CompId::QuestionCard => {
            let (i, d) = index(QUESTION_CARD_AXES, QUESTION_CARD_DEFAULTS, variant);
            QUESTION_CARD_GEOM[i][d]
        }
        CompId::Segmented => {
            let (i, d) = index(SEGMENTED_AXES, SEGMENTED_DEFAULTS, variant);
            SEGMENTED_GEOM[i][d]
        }
        CompId::DiffBlock => {
            let (i, d) = index(DIFF_BLOCK_AXES, DIFF_BLOCK_DEFAULTS, variant);
            DIFF_BLOCK_GEOM[i][d]
        }
        CompId::EmptyState => {
            let (i, d) = index(EMPTY_STATE_AXES, EMPTY_STATE_DEFAULTS, variant);
            EMPTY_STATE_GEOM[i][d]
        }
        CompId::TextInput => {
            let (i, d) = index(TEXT_INPUT_AXES, TEXT_INPUT_DEFAULTS, variant);
            TEXT_INPUT_GEOM[i][d]
        }
        CompId::RailItem => {
            let (i, d) = index(RAIL_ITEM_AXES, RAIL_ITEM_DEFAULTS, variant);
            RAIL_ITEM_GEOM[i][d]
        }
        CompId::Toast => {
            let (i, d) = index(TOAST_AXES, TOAST_DEFAULTS, variant);
            TOAST_GEOM[i][d]
        }
        CompId::Tooltip => {
            let (i, d) = index(TOOLTIP_AXES, TOOLTIP_DEFAULTS, variant);
            TOOLTIP_GEOM[i][d]
        }
    }
}

/// The word a screen reader speaks for component ID in VARIANT, if it has one.
pub fn label(id: CompId, variant: &[&str]) -> Option<&'static str> {
    match id {
        CompId::Row => ROW_LABEL[index(ROW_AXES, ROW_DEFAULTS, variant).0],
        CompId::Button => BUTTON_LABEL[index(BUTTON_AXES, BUTTON_DEFAULTS, variant).0],
        CompId::KeyHint => KEY_HINT_LABEL[index(KEY_HINT_AXES, KEY_HINT_DEFAULTS, variant).0],
        CompId::AgentMark => AGENT_MARK_LABEL[index(AGENT_MARK_AXES, AGENT_MARK_DEFAULTS, variant).0],
        CompId::Progress => PROGRESS_LABEL[index(PROGRESS_AXES, PROGRESS_DEFAULTS, variant).0],
        CompId::SectionHeader => SECTION_HEADER_LABEL[index(SECTION_HEADER_AXES, SECTION_HEADER_DEFAULTS, variant).0],
        CompId::Card => CARD_LABEL[index(CARD_AXES, CARD_DEFAULTS, variant).0],
        CompId::Chip => CHIP_LABEL[index(CHIP_AXES, CHIP_DEFAULTS, variant).0],
        CompId::StatusDot => STATUS_DOT_LABEL[index(STATUS_DOT_AXES, STATUS_DOT_DEFAULTS, variant).0],
        CompId::RangeBar => RANGE_BAR_LABEL[index(RANGE_BAR_AXES, RANGE_BAR_DEFAULTS, variant).0],
        CompId::TimeAxis => TIME_AXIS_LABEL[index(TIME_AXIS_AXES, TIME_AXIS_DEFAULTS, variant).0],
        CompId::Tab => TAB_LABEL[index(TAB_AXES, TAB_DEFAULTS, variant).0],
        CompId::QuestionCard => QUESTION_CARD_LABEL[index(QUESTION_CARD_AXES, QUESTION_CARD_DEFAULTS, variant).0],
        CompId::Segmented => SEGMENTED_LABEL[index(SEGMENTED_AXES, SEGMENTED_DEFAULTS, variant).0],
        CompId::DiffBlock => DIFF_BLOCK_LABEL[index(DIFF_BLOCK_AXES, DIFF_BLOCK_DEFAULTS, variant).0],
        CompId::EmptyState => EMPTY_STATE_LABEL[index(EMPTY_STATE_AXES, EMPTY_STATE_DEFAULTS, variant).0],
        CompId::TextInput => TEXT_INPUT_LABEL[index(TEXT_INPUT_AXES, TEXT_INPUT_DEFAULTS, variant).0],
        CompId::RailItem => RAIL_ITEM_LABEL[index(RAIL_ITEM_AXES, RAIL_ITEM_DEFAULTS, variant).0],
        CompId::Toast => TOAST_LABEL[index(TOAST_AXES, TOAST_DEFAULTS, variant).0],
        CompId::Tooltip => TOOLTIP_LABEL[index(TOOLTIP_AXES, TOOLTIP_DEFAULTS, variant).0],
    }
}

/// The face of component ID in VARIANT: its kit face, or `default` when it has none.
pub fn face(id: CompId, variant: &[&str]) -> FaceId {
    match id {
        CompId::Row => ROW_FACE[index(ROW_AXES, ROW_DEFAULTS, variant).0],
        CompId::Button => BUTTON_FACE[index(BUTTON_AXES, BUTTON_DEFAULTS, variant).0],
        CompId::KeyHint => KEY_HINT_FACE[index(KEY_HINT_AXES, KEY_HINT_DEFAULTS, variant).0],
        CompId::AgentMark => AGENT_MARK_FACE[index(AGENT_MARK_AXES, AGENT_MARK_DEFAULTS, variant).0],
        CompId::Progress => PROGRESS_FACE[index(PROGRESS_AXES, PROGRESS_DEFAULTS, variant).0],
        CompId::SectionHeader => SECTION_HEADER_FACE[index(SECTION_HEADER_AXES, SECTION_HEADER_DEFAULTS, variant).0],
        CompId::Card => CARD_FACE[index(CARD_AXES, CARD_DEFAULTS, variant).0],
        CompId::Chip => CHIP_FACE[index(CHIP_AXES, CHIP_DEFAULTS, variant).0],
        CompId::StatusDot => STATUS_DOT_FACE[index(STATUS_DOT_AXES, STATUS_DOT_DEFAULTS, variant).0],
        CompId::RangeBar => RANGE_BAR_FACE[index(RANGE_BAR_AXES, RANGE_BAR_DEFAULTS, variant).0],
        CompId::TimeAxis => TIME_AXIS_FACE[index(TIME_AXIS_AXES, TIME_AXIS_DEFAULTS, variant).0],
        CompId::Tab => TAB_FACE[index(TAB_AXES, TAB_DEFAULTS, variant).0],
        CompId::QuestionCard => QUESTION_CARD_FACE[index(QUESTION_CARD_AXES, QUESTION_CARD_DEFAULTS, variant).0],
        CompId::Segmented => SEGMENTED_FACE[index(SEGMENTED_AXES, SEGMENTED_DEFAULTS, variant).0],
        CompId::DiffBlock => DIFF_BLOCK_FACE[index(DIFF_BLOCK_AXES, DIFF_BLOCK_DEFAULTS, variant).0],
        CompId::EmptyState => EMPTY_STATE_FACE[index(EMPTY_STATE_AXES, EMPTY_STATE_DEFAULTS, variant).0],
        CompId::TextInput => TEXT_INPUT_FACE[index(TEXT_INPUT_AXES, TEXT_INPUT_DEFAULTS, variant).0],
        CompId::RailItem => RAIL_ITEM_FACE[index(RAIL_ITEM_AXES, RAIL_ITEM_DEFAULTS, variant).0],
        CompId::Toast => TOAST_FACE[index(TOAST_AXES, TOAST_DEFAULTS, variant).0],
        CompId::Tooltip => TOOLTIP_FACE[index(TOOLTIP_AXES, TOOLTIP_DEFAULTS, variant).0],
    }
}
